from os import path
import re
from subprocess import PIPE, Popen, STDOUT
from ta_tti_parser.utils import change_file_permissions, get_simple_logger, get_fsm_sw_version

FILES_DIR = '/tmp/tti_parser/'


class TtiDatParser(object):
    """Parse bin files to txt."""
    def __init__(self):
        # type: () -> None
        """Prepare before action."""
        self.logger = get_simple_logger(logger='', logger_name='tti_parser', stream=True,
                                        full_path=path.join(FILES_DIR, 'ta_tti_parser.log'))
        self.sw_version = self.get_sw_version()
        self.parser_base_dir = path.join(FILES_DIR, self.sw_version)
        self.package = []
        self.parser_bin = {'FDD': '', 'TDD': ''}

    def get_sw_version(self):
        """Get sw_version"""
        version = get_fsm_sw_version(self.logger, 'enb')
        return _correct_build_for_trunk(version)

    def parse_file(self, bin_filename):
        # type: (str) -> str
        """
        Parse TTI file using external tools.

        :param bin_filename: full path to binary *.dat file
        :raise AttributeError, IOError
        """
        if not bin_filename:
            msg = 'No traces found. Cannot parse.'
            self.logger.info(msg)
            raise IOError(msg)

        if bin_filename.endswith('.txt'):
            self.logger.debug("File {} ends with .txt. Assuming it's already parsed.".format(bin_filename))
            return bin_filename

        self.logger.debug('Filename ready for parsing: {}'.format(bin_filename))
        tt = dat_trace_type(bin_filename)
        self.logger.debug('Detected trace type: {}'.format(tt))
        self._prepare_parser(tt)
        return self._parse_with_parser(tt, bin_filename)

    def _prepare_parser(self, _trace_type):
        if not self.parser_bin[_trace_type]:
            self.parser_bin[_trace_type] = get_parser_path(self.parser_base_dir, _trace_type)
            change_file_permissions(self.logger, self.parser_bin[_trace_type], 0o755)

    def _parse_with_parser(self, _trace_type, binary_file):
        # type: (str, str) -> str
        parsed_file = '{}.txt'.format(binary_file[:-4])
        cmd = self._build_parser_cmd(_trace_type, binary_file, parsed_file)
        proc = Popen(cmd, stdout=PIPE, stderr=STDOUT, shell=True, cwd=self.parser_base_dir)
        stdout, stderr = proc.communicate()
        stdout = stdout.decode() if stdout is not None else ""
        stderr = stderr.decode() if stderr is not None else ""
        self.logger.debug('Output from parser:\n {}'.format(_replace_ascii_line_endings(stdout)))
        self.logger.debug('Errors: {}'.format(stderr))

        if proc.returncode != 0:
            raise IOError(stderr)
        _check_errors_in_output(stdout)
        return parsed_file

    def _build_parser_cmd(self, tt, input_f, output_f):
        cmd = ' '.join([self.parser_bin[tt], input_f, output_f, '-excelMode' if tt == 'FDD' else ''])
        self.logger.debug(cmd)
        return cmd


def _check_errors_in_output(inp):
    """Third party parser can inform about failure in stdout instead of stderr."""
    for s in ['cannot open file', 'Exit with ERROR']:
        if s in inp:
            raise IOError('Check debug log. Found: {}'.format(inp.splitlines()[-1]))


def _replace_ascii_line_endings(inp):
    return inp.replace('\n', '\r')


def dat_trace_type(_file):
    # type: (str) -> str
    """
    Reads first 300 bytes from binary file.
    Returns used technology (TDD/FDD).
    :return technology as a str
    :raises IOError when type is not recognized
    """
    with open(_file, 'rb') as f:
        fst_line = f.read(300)
    fdd = re.compile('R:(\\w+):'.encode())
    tdd = re.compile('(\\w+)'.encode())

    fdd_result = fdd.search(fst_line)
    if fdd_result:
        return 'FDD'

    tdd_result = tdd.search(fst_line)
    if tdd_result:
        return 'TDD'

    raise IOError('Unknown trace type, neither FDD nor TDD')


def get_parser_path(base_dir, parser_type):
    # type: (str, str) -> str
    """Return path to parser. Support older parser paths."""
    parser_filename = {
        'FDD': 'FDD_parser/tti_trace_parser_wmp-linux.exe',
        'TDD': 'TDD_parser/DevC_tti_trace_parser_64'}
    return path.join(base_dir, parser_filename[parser_type])


def _correct_build_for_trunk(build):
    # type: (str) -> str
    trunk_identifier = '00'
    regex = re.compile('(^[A-Z]+)(\\d+[^_]+)(_.*_9999_)(.*)')

    trunk = regex.match(build)
    if trunk:
        build_in_parts = list(trunk.groups())
        build_in_parts[1] = trunk_identifier
        return ''.join(build_in_parts)
    return build
